import { existsSync } from 'node:fs';
import { join } from 'node:path';
import { z } from 'zod';
import { VALID_RELATIVE_PATH_REGEX } from '../../../dev-center/components/validations/common.js';
import type { ExtensionDef } from '../generate-schema/types.js';
import { defineField } from '../generate-schema/definitions.js';
import { generateHttpEndpoint } from './generate.js';
import { resolveHttpEndpointsTarget } from './resolve.js';

const schema = z.object({
  extensionType: z.literal('HTTP_ENDPOINT'),
  name: z
    .string()
    .regex(VALID_RELATIVE_PATH_REGEX)
    .describe(
      defineField({
        title: 'Name',
        description:
          'Lowercase alphanumeric and hyphens, optionally in slash-separated segments (no leading or trailing slash). Used to name the function file and determines the route it is exposed at.',
      })
    ),
});

export const httpEndpoint: ExtensionDef<typeof schema> = {
  title: 'HTTP Endpoint',
  description: 'Handle HTTP requests with backend code',
  group: 'Backend',
  projectTypes: ['App'],
  documentation:
    'https://dev.wix.com/docs/build-apps/develop-your-app/develop-an-app-with-the-cli/supported-extensions/backend/http-endpoints/about-http-endpoints',
  zodSchema: schema,
  validate: async (projectFolder, data) => {
    const { endpointsDir } = await resolveHttpEndpointsTarget(projectFolder);

    return existsSync(join(endpointsDir, `${data.name}.ts`))
      ? `An HTTP endpoint named '${data.name}' already exists.`
      : null;
  },
  generate: ({ projectFolder, data }) =>
    generateHttpEndpoint(projectFolder, data.name),
};
