import { join } from 'node:path';
import { getExtensionDir } from './definitions.js';

export function getBackendEventExtensionsDir(projectFolder: string) {
  return join(getExtensionDir(projectFolder), 'backend', 'events');
}

export function getBackendEventExtensionPath(
  projectFolder: string,
  extensionPath: string
) {
  return join(getBackendEventExtensionsDir(projectFolder), extensionPath);
}

export function getBackendPluginExtensionsDir(projectFolder: string) {
  return join(getExtensionDir(projectFolder), 'backend', 'service-plugins');
}

export function getBackendPluginExtensionPath(
  projectFolder: string,
  extensionPath: string
) {
  return join(getBackendPluginExtensionsDir(projectFolder), extensionPath);
}

export function getBackendDataCollectionsExtensionsDir(projectFolder: string) {
  return join(getExtensionDir(projectFolder), 'backend', 'data-collections');
}

export function getBackendDataCollectionsExtensionPath(
  projectFolder: string,
  extensionPath: string
) {
  return join(
    getBackendDataCollectionsExtensionsDir(projectFolder),
    extensionPath
  );
}

export function getBackendAppToolsExtensionsDir(projectFolder: string) {
  return join(getExtensionDir(projectFolder), 'backend', 'app-tools');
}

export function getBackendAppToolsExtensionPath(
  projectFolder: string,
  extensionPath: string
) {
  return join(getBackendAppToolsExtensionsDir(projectFolder), extensionPath);
}

// HTTP endpoints are file-based routes rather than registered extensions.
// `@wix/astro` projects serve them from `src/pages/api` at `/api/<name>`;
// standalone `@wix/custom-extensions` projects discover them from
// `src/endpoints` (the runtime's default apiDir) at `/<name>`.
export function getAstroHttpEndpointsDir(projectFolder: string) {
  return join(projectFolder, 'src', 'pages', 'api');
}

export function getStandaloneHttpEndpointsDir(projectFolder: string) {
  return join(projectFolder, 'src', 'api');
}
