import { z } from 'zod';
import type {
  EmbedCategory,
  EmbeddedScriptPlacement,
} from '@wix/ambassador-devcenter-apps-v1-app-old/types';
import { getEmbeddedScriptExtensionsDir } from '@wix/cli-astro-definitions';
import {
  folderExistsMessage,
  pathAvailableValidation,
} from '../../../dev-center/components/validations/common.js';
import type { ExtensionDef } from '../generate-schema/types.js';
import { defineField } from '../generate-schema/definitions.js';
import { enrichWithDerivedFolder } from '../utils/derive-folder.js';
import type { WithDerivedFolder } from '../utils/derive-folder.js';
import { generateEmbeddedScript } from './generate.js';

const schema = z.object({
  extensionType: z.literal('EMBEDDED_SCRIPT'),
  scriptType: z
    .union([
      z.literal('ESSENTIAL').describe(
        defineField({
          title: 'Essential',
          description: 'Core functionality crucial to site operation.',
        })
      ),
      z.literal('FUNCTIONAL').describe(
        defineField({
          title: 'Functional',
          description:
            "Remembers site visitors' choices to improve experience.",
        })
      ),
      z.literal('ANALYTICS').describe(
        defineField({
          title: 'Analytics',
          description: 'Provides statistics on how visitors use the site.',
        })
      ),
      z.literal('ADVERTISING').describe(
        defineField({
          title: 'Advertising',
          description:
            'Adds advertising content or advertising tracking to the site.',
        })
      ),
    ])
    .describe(
      defineField({
        title: 'Script type',
        description: 'Determines the consent category of the script.',
      })
    ),
  placement: z
    .union([
      z.literal('HEAD').describe(
        defineField({
          title: 'Head',
          description:
            'Inside <head>. Use for tags that must load before the page renders.',
        })
      ),
      z.literal('BODY_START').describe(
        defineField({
          title: 'Body Start',
          description:
            'Right after <body> opens. Runs before page content renders.',
        })
      ),
      z.literal('BODY_END').describe(
        defineField({
          title: 'Body End',
          description:
            'At the end of <body>. Runs after page content — safest default.',
        })
      ),
    ])
    .describe(
      defineField({
        title: 'Placement',
        description: 'Where in the page HTML the script is injected.',
      })
    ),
  name: z.string().describe(
    defineField({
      title: 'Name',
      description: 'This will be used as the folder and files name.',
    })
  ),
});

export const embeddedScript: ExtensionDef<
  typeof schema,
  WithDerivedFolder<typeof schema>
> = {
  title: 'Embedded Script',
  description: 'Add a custom script to your site pages',
  group: 'Site',
  projectTypes: ['App'],
  documentation:
    'https://dev.wix.com/docs/overview/extensions-framework/site-extensions/embedded-scripts',
  zodSchema: schema,
  enrich: (data) => enrichWithDerivedFolder(data, { sourceField: 'name' }),
  validate: async (projectFolder, data) => {
    const isAvailable = pathAvailableValidation(
      getEmbeddedScriptExtensionsDir(projectFolder)
    )(data.folder);
    return isAvailable
      ? null
      : folderExistsMessage('script', data.folder, 'name');
  },
  // scriptType and placement are Zod string literals but generateEmbeddedScript expects TypeScript enums
  generate: ({ projectFolder, data }) =>
    generateEmbeddedScript(
      projectFolder,
      data.folder,
      data.name,
      data.scriptType as EmbedCategory,
      data.placement as EmbeddedScriptPlacement
    ),
};
