import path from 'node:path';
import { componentGenerator } from '@wix/gena';
import { resolveHttpEndpointsTarget } from './resolve.js';

const HTTP_ENDPOINT_TEMPLATE = path.resolve(
  __dirname,
  '../templates/astro/http-endpoint'
);

// First @wix/custom-extensions release that discovers src/endpoints by
// default and exposes the endpoint handler types under ./types. No @wix/astro
// minimum is needed: endpoints there are native Astro routes.
const MIN_CUSTOM_EXTENSIONS_VERSION = '^0.2.18';

export async function generateHttpEndpoint(
  projectFolder: string,
  name: string
) {
  const target = await resolveHttpEndpointsTarget(projectFolder);

  return componentGenerator({
    template: HTTP_ENDPOINT_TEMPLATE,
    projectFolder,
    cwd: target.endpointsDir,
    ...(target.isCustomExtensionsProject
      ? {
          dynamicPackages: {
            '@wix/custom-extensions': MIN_CUSTOM_EXTENSIONS_VERSION,
          },
        }
      : {}),
    data: {
      route: name,
      endpointRoute: target.endpointRoute(name),
      typesPackage: target.typesPackage,
    },
  });
}
