import {
  getAstroHttpEndpointsDir,
  getStandaloneHttpEndpointsDir,
} from '@wix/cli-astro-definitions';
import { isStandaloneExtensionsProject } from '@wix/cli-custom-extensions';

interface HttpEndpointsTarget {
  endpointsDir: string;
  endpointRoute: (name: string) => string;
  isCustomExtensionsProject: boolean;
  typesPackage: '@wix/custom-extensions/types' | 'astro';
}

/**
 * Resolves where HTTP endpoint files live for this project. `@wix/astro`
 * projects serve `src/pages` natively, so endpoints go under `src/pages/api`
 * and are exposed at `/api/<name>`; standalone `@wix/custom-extensions`
 * projects discover `src/endpoints` by default and expose routes at
 * `/<name>`.
 */
export async function resolveHttpEndpointsTarget(
  projectFolder: string
): Promise<HttpEndpointsTarget> {
  if (await isStandaloneExtensionsProject(projectFolder)) {
    return {
      endpointsDir: getStandaloneHttpEndpointsDir(projectFolder),
      endpointRoute: (name) => `/${name}`,
      isCustomExtensionsProject: true,
      typesPackage: '@wix/custom-extensions/types',
    };
  }

  return {
    endpointsDir: getAstroHttpEndpointsDir(projectFolder),
    endpointRoute: (name) => `/api/${name}`,
    isCustomExtensionsProject: false,
    typesPackage: 'astro',
  };
}
